import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import * as fs from 'fs';
import * as path from 'path';

// Create the scene from the original Three.js file
const scene = createScene();

// Convert InstancedMesh to regular meshes for OBJ export
// OBJExporter doesn't handle InstancedMesh, so we need to convert them
function convertInstancedMeshes(object) {
  const instancedMeshes = [];

  object.traverse((child) => {
    if (child instanceof THREE.InstancedMesh) {
      instancedMeshes.push(child);
    }
  });

  instancedMeshes.forEach((instancedMesh) => {
    const parent = instancedMesh.parent;
    const geometry = instancedMesh.geometry;
    const material = instancedMesh.material;
    const count = instancedMesh.count;

    // Create a group to hold all instances
    const instanceGroup = new THREE.Group();
    instanceGroup.name = instancedMesh.name + '_group';

    // Get the world matrix of the instanced mesh
    const instancedMeshWorldMatrix = new THREE.Matrix4();
    instancedMesh.updateWorldMatrix(true, false);
    instancedMeshWorldMatrix.copy(instancedMesh.matrixWorld);

    // Create individual meshes for each instance
    for (let i = 0; i < count; i++) {
      const matrix = new THREE.Matrix4();
      instancedMesh.getMatrixAt(i, matrix);

      const mesh = new THREE.Mesh(geometry.clone(), material);
      mesh.name = `${instancedMesh.name}_${i}`;
      mesh.applyMatrix4(matrix);

      instanceGroup.add(mesh);
    }

    // Copy the transform from the instanced mesh
    instanceGroup.position.copy(instancedMesh.position);
    instanceGroup.rotation.copy(instancedMesh.rotation);
    instanceGroup.scale.copy(instancedMesh.scale);

    // Replace the instanced mesh with the group
    if (parent) {
      parent.add(instanceGroup);
      parent.remove(instancedMesh);
    }
  });
}

// Convert instanced meshes to regular meshes
convertInstancedMeshes(scene);

// Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
// In Three.js, Y is up. In Blender, Z is up.
// A -90 degree rotation around X converts Y-up to Z-up
const blenderConversionMatrix = new THREE.Matrix4();
blenderConversionMatrix.makeRotationX(-Math.PI / 2);

// Create a wrapper group to apply the rotation
const exportRoot = new THREE.Group();
exportRoot.add(scene);
exportRoot.applyMatrix4(blenderConversionMatrix);

// Update all matrices
exportRoot.updateMatrixWorld(true);

// Export to OBJ format
const exporter = new OBJExporter();
const objData = exporter.parse(exportRoot);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write the OBJ file
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log(`Successfully exported to ${outputPath}`);
console.log(`Total vertices: ${objData.split('\nv ').length - 1}`);
console.log(`Total faces: ${objData.split('\nf ').length - 1}`);
console.log('Coordinate system: Blender Z-up (applied -90° X-rotation)');

